/**
 * Kwara South Senatorial District electoral geography:
 *   senatorial district → federal constituency → LGA (7) → ward (83) → polling unit (682 enumerated / 907 current).
 *
 * LGA, ward and polling unit records come from the bundled INEC directory (see data/inec/README.md)
 * and are regenerated by `node scripts/parse-inec-directory.mjs`. Do not hand-edit the generated JSON.
 */

import { INEC_PU_DIRECTORY_2015, sourced, type Provenance, type Sourced } from '@/lib/provenance';

import generated from './kwara-south.generated.json';

export interface Lga {
  code: string;
  name: string;
  inecName: string;
  declaredWardCount: number;
  declaredPollingUnitCount: number;
}

export interface Ward {
  /** `${lgaCode}-${code}` — stable across INEC directory revisions. */
  id: string;
  lgaCode: string;
  code: string;
  name: string;
  inecName: string;
  declaredPollingUnitCount: number;
}

export interface PollingUnit {
  /** `${lgaCode}-${wardCode}-${code}`. */
  id: string;
  lgaCode: string;
  wardCode: string;
  code: string;
  name: string;
  inecName: string;
}

export type FederalConstituencyId = 'ifelodun_offa_oyun' | 'ekiti_irepodun_isin_oke_ero';

export interface FederalConstituency {
  id: FederalConstituencyId;
  name: string;
  shortName: string;
  lgaCodes: string[];
}

export const FEDERAL_CONSTITUENCY_PROVENANCE: Provenance = {
  kind: 'official',
  publisher: 'Independent National Electoral Commission (INEC)',
  document: 'Kwara South Senatorial District — Federal Constituency delimitation',
  revision: 'Constitutional delineation',
};

/**
 * The two federal constituencies that partition Kwara South's seven local government areas.
 * Used as the natural sub-district operational grouping across power maps, comms, and OSINT.
 */
export const FEDERAL_CONSTITUENCIES: FederalConstituency[] = [
  {
    id: 'ifelodun_offa_oyun',
    name: 'Ifelodun / Offa / Oyun',
    shortName: 'Ifelodun–Offa–Oyun',
    lgaCodes: ['05', '13', '15'], // Ifelodun, Offa, Oyun
  },
  {
    id: 'ekiti_irepodun_isin_oke_ero',
    name: 'Ekiti / Irepodun / Isin / Oke-Ero',
    shortName: 'Ekiti–Irepodun–Isin–Oke-Ero',
    lgaCodes: ['04', '09', '10', '14'], // Ekiti, Irepodun, Isin, Oke-Ero
  },
];

export const lgas: Lga[] = generated.lgas;
export const wards: Ward[] = generated.wards;
export const pollingUnits: PollingUnit[] = generated.pollingUnits;

export const sourceMeta = generated.source;

const lgaByCode = new Map(lgas.map((l) => [l.code, l]));
const wardById = new Map(wards.map((w) => [w.id, w]));
const constituencyByLgaCode = new Map<string, FederalConstituency>();
for (const fc of FEDERAL_CONSTITUENCIES) {
  for (const code of fc.lgaCodes) constituencyByLgaCode.set(code, fc);
}

export function getLga(code: string): Lga | undefined {
  return lgaByCode.get(code);
}

export function getWard(id: string): Ward | undefined {
  return wardById.get(id);
}

export function wardsInLga(lgaCode: string): Ward[] {
  return wards.filter((w) => w.lgaCode === lgaCode);
}

export function pollingUnitsInWard(wardId: string): PollingUnit[] {
  const ward = wardById.get(wardId);
  if (!ward) return [];
  return pollingUnits.filter((p) => p.lgaCode === ward.lgaCode && p.wardCode === ward.code);
}

export function constituencyOfLga(lgaCode: string): FederalConstituency | undefined {
  return constituencyByLgaCode.get(lgaCode);
}

export function lgasInConstituency(id: FederalConstituencyId): Lga[] {
  const fc = FEDERAL_CONSTITUENCIES.find((x) => x.id === id);
  if (!fc) return [];
  return fc.lgaCodes.map((c) => lgaByCode.get(c)).filter((l): l is Lga => Boolean(l));
}

export function wardsInConstituency(id: FederalConstituencyId): Ward[] {
  const codes = new Set(FEDERAL_CONSTITUENCIES.find((x) => x.id === id)?.lgaCodes ?? []);
  return wards.filter((w) => codes.has(w.lgaCode));
}

/** Structural totals, carrying their INEC provenance so the UI can badge staleness. */
export const totals = {
  lgas: sourced(lgas.length, INEC_PU_DIRECTORY_2015),
  wards: sourced(wards.length, INEC_PU_DIRECTORY_2015),
  pollingUnits: sourced(pollingUnits.length, INEC_PU_DIRECTORY_2015),
} satisfies Record<string, Sourced<number>>;
